package com.hasibul.megh;
import android.appwidget.*;import android.content.*;import android.app.*;import android.widget.*;import org.json.*;
public class MeghWidget extends AppWidgetProvider {
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){refresh(c);}
 static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);var p=c.getSharedPreferences("megh",0);for(int id:m.getAppWidgetIds(new ComponentName(c,MeghWidget.class))){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);boolean bn=p.getString("lang","en").equals("bn");v.setTextViewText(R.id.title,"Megh • "+p.getString("city","Dhaka"));try{JSONObject j=new JSONObject(p.getString("weather",""));String t=Math.round(j.getJSONObject("current").getDouble("temperature_2m"))+"°";if(bn){for(int i=0;i<10;i++)t=t.replace((char)('0'+i),(char)('০'+i));}v.setTextViewText(R.id.temp,t);String date=new java.text.SimpleDateFormat("HH:mm",java.util.Locale.US).format(new java.util.Date(p.getLong("updated",0)));v.setTextViewText(R.id.detail,(bn?"সর্বশেষ আপডেট ":"Updated ")+date+" • "+(bn?"বিস্তারিত দেখতে চাপো":"Tap for forecast"));String theme=p.getString("theme","blue");v.setInt(R.id.temp,"setTextColor",theme.equals("night")?0xff7e63b6:0xff17445e);}catch(Exception ignored){}v.setOnClickPendingIntent(R.id.title,PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(R.id.temp,PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}}
}
